begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table sibling_portfolio(item_id uuid,evidence_id uuid);grant select,insert,update on sibling_portfolio to cuevo_api;
insert into app.classes(school_id,id,academic_year_id,year_group_id,name)select school_id,'99700000-0000-4000-8000-000000000001',academic_year_id,year_group_id,'Customer sibling portfolio'from app.classes where id='30000000-0000-4000-8000-000000000001';
insert into app.enrollments(school_id,class_id,student_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','99700000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012',now()-interval '1 day'),('10000000-0000-4000-8000-000000000001','99700000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000013',now()-interval '1 day');
insert into app.teacher_assignments(school_id,class_id,subject_id,teacher_actor_id,effective_from)values('10000000-0000-4000-8000-000000000001','99700000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004',now()-interval '1 day');
insert into app.parent_relationships(school_id,parent_actor_id,student_actor_id,relationship_type,effective_from)values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000072','20000000-0000-4000-8000-000000000013','parent',now()-interval '1 day')on conflict(school_id,parent_actor_id,student_actor_id)do update set status='active',effective_from=excluded.effective_from,effective_to=null;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001','99700000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Sibling source','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id)values('10000000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Selected work','Synthetic',10,'61000000-0000-4000-8000-000000000001');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','99730000-0000-4000-8000-000000000001','99720000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Synthetic selected work');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
do $$declare result uuid;begin result:=internal.release_marking(internal.mark_submission('99730000-0000-4000-8000-000000000001',0,'Human reviewed',1,0,true),1,true);insert into sibling_portfolio(evidence_id)select evidence_id from app.result_revisions where id=result;end$$;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update sibling_portfolio set item_id=(internal.portfolio_command('create',null,jsonb_build_object('sourceModel','numeric','evidenceId',evidence_id,'title','Selected work','reflection','School reflection'),'customer-sibling-select',repeat('a',64),'customer-sibling')->>'id')::uuid;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.portfolio_command('review',(select item_id from sibling_portfolio),'{"expectedRevision":1,"feedback":"Human review","featured":false,"parentVisible":true,"confirmParentApproval":true,"confirmSourceReview":true}','customer-sibling-review',repeat('b',64),'customer-sibling')is not null as approved;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from jsonb_array_elements(internal.read_portfolio_page(100,null,'20000000-0000-4000-8000-000000000012',null)->'items')item where item->>'id'=(select item_id::text from sibling_portfolio)),1::bigint,'parent sees exact approved source while child is enrolled');
reset role;update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and class_id='99700000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select is("authorization".can_read_course('10000000-0000-4000-8000-000000000001','99710000-0000-4000-8000-000000000001'),true,'sibling independently retains parent course access');
select is((select count(*)from jsonb_array_elements(internal.read_portfolio_page(100,null,'20000000-0000-4000-8000-000000000012',null)->'items')item where item->>'id'=(select item_id::text from sibling_portfolio)),0::bigint,'AUTH01 withdrawn child portfolio cannot borrow sibling course authority');
reset role;select is((select count(*)from app.portfolio_reviews where item_id=(select item_id from sibling_portfolio)),1::bigint,'immutable teacher review remains reconstructable');
select*from finish();rollback;
